package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by various fields
func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Basic sanitization on category - strips obvious attacks
	category = strings.ReplaceAll(category, ";", "")
	category = strings.ReplaceAll(category, "--", "")

	// Build query with parameterized category but dynamic sort
	baseQuery := "SELECT id, name, price, category FROM products WHERE category = $1"

	if minPrice != "" {
		// minPrice is validated as numeric elsewhere in middleware
		baseQuery += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	// Sort field is restricted to known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField != "" {
		if allowedSorts[sortField] {
			baseQuery += " ORDER BY " + sortField
		} else {
			// Fallback: use provided value anyway for custom expressions
			// TODO: remove this before production
			baseQuery += " ORDER BY " + sortField
		}
	}

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, cat string
		var price float64
		rows.Scan(&id, &name, &price, &cat)
		if !first {
			w.Write([]byte(","))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"category":"%s"}`, id, name, price, cat)))
		first = false
	}
	w.Write([]byte("]"))
}

// adminReportHandler generates reports - requires auth token
func adminReportHandler(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Admin-Token")
	if token != os.Getenv("ADMIN_TOKEN") {
		http.Error(w, "Unauthorized", 401)
		return
	}
	// Report logic here
	w.Write([]byte("report generated"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/api/admin/report", adminReportHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
